INSERT INTO cadence_templates (slug, name, summary, visibility, status, duration_weeks, discipline, team_size_min, team_size_max, work_mode, goals, definition, clone_count, featured) VALUES ('four-week-design-cadence', 'The Four-Week Design Cadence', 'One weekly meeting slot, four themes rotating through it: Learning, Innovation, Alignment, Showcase + Spotlight. The flagship — see PLAN.md §1.3.', 'public', 'published', 52, 'Product Design', 4, 14, 'remote', '["A predictable rhythm that still covers craft, exploration, alignment, and visibility"]', '{"slots":[{"name":"Weekly Design Meeting","freq":"weekly","byweekday":4,"durationMin":60,"rotation":[{"position":0,"ritualSlug":"design-crit","label":null},{"position":1,"ritualSlug":"ai-new-tech-demo","label":null},{"position":2,"ritualSlug":"staff-meeting","label":null},{"position":3,"ritualSlug":"product-showcase","label":null}]}],"standalone":[{"ritualSlug":"quarterly-ritual-audit","dayOffset":84,"spanWeeks":null},{"ritualSlug":"quarterly-ritual-audit","dayOffset":175,"spanWeeks":null},{"ritualSlug":"quarterly-ritual-audit","dayOffset":266,"spanWeeks":null},{"ritualSlug":"team-offsite","dayOffset":329,"spanWeeks":null}]}', 0, 1);
INSERT INTO cadence_templates (slug, name, summary, visibility, status, duration_weeks, discipline, team_size_min, team_size_max, work_mode, goals, definition, clone_count, featured) VALUES ('research-study-week', 'Research Study Week', 'A focused, one-week push to get a real answer fast: assumptions mapped, sessions run, findings shared — not a month-long drift.', 'public', 'published', 1, 'UX Research', 2, 8, 'remote', '["Answer one specific question with real users, fast"]', '{"slots":[],"standalone":[{"ritualSlug":"assumption-mapping","dayOffset":0,"spanWeeks":null},{"ritualSlug":"usability-watch-party","dayOffset":2,"spanWeeks":null},{"ritualSlug":"research-readout","dayOffset":4,"spanWeeks":null}]}', 0, 0);
INSERT INTO cadence_templates (slug, name, summary, visibility, status, duration_weeks, discipline, team_size_min, team_size_max, work_mode, goals, definition, clone_count, featured) VALUES ('new-design-team-first-quarter', 'New Design Team, First Quarter', 'Deliberately light: one weekly meeting, working agreements set early, nothing else competing for attention while the team finds its footing.', 'public', 'published', 12, 'Product Design', 2, 6, 'hybrid', '["Set norms before adding ritual load","Avoid over-scheduling a team that''s still forming"]', '{"slots":[{"name":"Staff Meeting","freq":"weekly","byweekday":1,"durationMin":45,"rotation":[{"position":0,"ritualSlug":"staff-meeting","label":null}]}],"standalone":[{"ritualSlug":"working-with-me","dayOffset":3,"spanWeeks":null},{"ritualSlug":"working-agreement-refresh","dayOffset":14,"spanWeeks":null},{"ritualSlug":"random-coffee","dayOffset":28,"spanWeeks":null}]}', 0, 0);
INSERT INTO cadence_templates (slug, name, summary, visibility, status, duration_weeks, discipline, team_size_min, team_size_max, work_mode, goals, definition, clone_count, featured) VALUES ('design-systems-team', 'Design Systems Team', 'Office hours every week, a contribution/adoption review every month, and a planning checkpoint — the rhythm a systems team runs on.', 'public', 'published', 26, 'Design Systems', 3, 10, 'remote', '["Keep the system easy to contribute to","Catch adoption gaps before they calcify"]', '{"slots":[{"name":"Design System Office Hours","freq":"weekly","byweekday":2,"durationMin":30,"rotation":[{"position":0,"ritualSlug":"design-system-office-hours","label":null}]},{"name":"Contribution & Adoption Review","freq":"monthly","byweekday":1,"nth":2,"durationMin":45,"rotation":[{"position":0,"ritualSlug":"decision-log-review","label":null}]}],"standalone":[{"ritualSlug":"quarterly-planning","dayOffset":0,"spanWeeks":null},{"ritualSlug":"tech-radar-review","dayOffset":84,"spanWeeks":null},{"ritualSlug":"quarterly-planning","dayOffset":91,"spanWeeks":null}]}', 0, 0);
INSERT INTO cadence_templates (slug, name, summary, visibility, status, duration_weeks, discipline, team_size_min, team_size_max, work_mode, goals, definition, clone_count, featured) VALUES ('small-team-under-6', 'Small Team / Under 6 People', 'One weekly slot, one monthly slot, nothing else. Proves the app is useful even when the team is too small for a heavier cadence.', 'public', 'published', 52, 'Product Design', 2, 6, 'hybrid', '["Stay aligned and reflective without over-scheduling a small team"]', '{"slots":[{"name":"Staff Meeting","freq":"weekly","byweekday":1,"durationMin":30,"rotation":[{"position":0,"ritualSlug":"staff-meeting","label":null}]},{"name":"Monthly Retro","freq":"monthly","byweekday":5,"nth":-1,"durationMin":45,"rotation":[{"position":0,"ritualSlug":"retro","label":null}]}],"standalone":[]}', 0, 0);
INSERT INTO cadence_templates (slug, name, summary, visibility, status, duration_weeks, discipline, team_size_min, team_size_max, work_mode, goals, definition, clone_count, featured) VALUES ('craft-focused-quarter', 'Craft-Focused Quarter', 'Crit every week, plus a portfolio review, an accessibility pass, and a polish pass — the natural landing place after a ritual audit flags weak craft signals.', 'public', 'published', 12, 'Product Design', 3, 12, 'hybrid', '["Raise the craft bar for a quarter","Follow up on a weak Team Ritual Audit craft score"]', '{"slots":[{"name":"Design Crit","freq":"weekly","byweekday":4,"durationMin":60,"rotation":[{"position":0,"ritualSlug":"design-crit","label":null}]}],"standalone":[{"ritualSlug":"portfolio-review","dayOffset":42,"spanWeeks":null},{"ritualSlug":"accessibility-review","dayOffset":21,"spanWeeks":null},{"ritualSlug":"design-qa-polish-pass","dayOffset":63,"spanWeeks":null}]}', 0, 0);
